import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Sequence Flow — View Agency Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-2-view-agency-dashboard/sequence-flow.md","filePath":"feature/agency-workspace/3-4-2-view-agency-dashboard/sequence-flow.md"}'),n={name:"feature/agency-workspace/3-4-2-view-agency-dashboard/sequence-flow.md"};function s(d,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-view-agency-dashboard" tabindex="-1">Sequence Flow — View Agency Dashboard <a class="header-anchor" href="#sequence-flow-—-view-agency-dashboard" aria-label="Permalink to &quot;Sequence Flow — View Agency Dashboard&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.2). This feature is <strong>proposed and not yet implemented</strong>: the system has no dashboard screen and no summary of Workspace, Member and Client counts. There is no dashboard route among the Agency routes that exist today. &gt; &gt; Updated 2026-09-23.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p><strong>There is no real sequence to describe yet.</strong> No dashboard route exists, and nothing counts Workspaces, Members, Clients or recent activity for an Agency. The steps below are an <strong>indicative draft</strong>, taken from the proposed interface described in <code>spec.md</code>. They are meant as a reference for the eventual design and are <strong>not a working flow</strong>.</p><h2 id="actors-proposed" tabindex="-1">Actors (proposed) <a class="header-anchor" href="#actors-proposed" aria-label="Permalink to &quot;Actors (proposed)&quot;">​</a></h2><ul><li><strong>Owner</strong></li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>, <code>agency_members</code>; the Workspace and Client Profile sources still have to be designed).</li></ul><h2 id="indicative-flow-draft-—-not-implemented" tabindex="-1">Indicative flow (draft — not implemented) <a class="header-anchor" href="#indicative-flow-draft-—-not-implemented" aria-label="Permalink to &quot;Indicative flow (draft — not implemented)&quot;">​</a></h2><ol><li>Owner → Client: opens the dashboard of an Agency.</li><li>Client → System: requests the dashboard summary of the Agency. <em>(Proposed — not yet implemented.)</em></li><li>System (proposed): a. Confirms the Agency exists and is not soft-deleted — otherwise <code>404 AGENCY_NOT_FOUND</code>. b. Confirms the caller is the Owner of the Agency — otherwise <code>403 FORBIDDEN</code>. c. Counts the Members of the Agency from the member records, which are available today. d. Counts the Workspaces of the Agency and the distinct Clients across them. <strong>The data source for these counts still has to be designed.</strong> e. Collects recent activity. <strong>The data source for recent activity is still undecided.</strong></li><li>System → Client: the summary with the Workspace count, the Member count, the Client count and the recent-activity list. <em>(Proposed shape, not fixed.)</em></li><li>Client: renders the dashboard.</li></ol><h2 id="error-paths-proposed-draft" tabindex="-1">Error paths (proposed, draft) <a class="header-anchor" href="#error-paths-proposed-draft" aria-label="Permalink to &quot;Error paths (proposed, draft)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Dashboard</td><td>Caller is not the Agency Owner</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Dashboard</td><td>Agency does not exist or is soft-deleted</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>No divergence from <code>spec.md</code>: that document already states that the feature is proposed and not yet implemented. This file only confirms that nothing has been built, and adds no new claim.</li></ul>',12)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
